// Build a small Matrix** manually for testing construct/free
static Matrix** makeIdentityImages(int count, int dim) {
    Matrix** imgs = malloc(count * sizeof(Matrix*));
    for (int i = 0; i < count; i++) imgs[i] = idMatrix(dim);
    return imgs;
}

void testConstructAndFreeRepresentation() {
    SECTION("constructRepresentation / freeRepresentation");
    Group* Z2 = constructZnGroup(2);

    CHECK(constructRepresentation(NULL, "X", NULL, 1, 1) == NULL, "NULL inputs");

    Matrix** imgs = makeIdentityImages(Z2->card, 2);
    Representation* rep = constructRepresentation(Z2, "Test", imgs, 2, 2);
    CHECK(rep != NULL, "rep constructed");
    CHECK(rep->group == Z2, "rep->group correct");
    CHECK(rep->images == imgs, "rep->images correct");
    CHECK(rep->mdim == 2, "rep->mdim set");
    CHECK(rep->dim == 2, "rep->dim set");
    CHECK(strcmp(rep->repr, "Test") == 0, "rep->repr copied");
    freeRepresentation(rep);

    freeRepresentation(NULL);
    CHECK(1, "freeRepresentation(NULL) safe");

    freeGroup(Z2);
}

