void testRegularRepresentation() {
    SECTION("regularRepresentation");
    CHECK(regularRepresentation(NULL) == NULL, "NULL group");

    Group* Z3 = constructZnGroup(3);
    Representation* rep = regularRepresentation(Z3);
    CHECK(rep != NULL, "rep built");
    CHECK(rep->dim == 3, "regular dim = |G|");
    CHECK(rep->mdim == 3, "regular mdim = |G|");

    // Identity image should be the identity matrix
    Matrix* I = rep->images[0];
    bool identityOk = true;
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++) {
            double expected = (i == j) ? 1.0 : 0.0;
            if (!approxReal(getEntry(I, i, j), expected, 1e-12)) identityOk = false;
        }
    CHECK(identityOk, "regular rep of identity is I");

    // Each image is a permutation matrix: each row/col has exactly one 1
    bool permOk = true;
    for (int g = 0; g < Z3->card; g++) {
        for (int i = 0; i < 3; i++) {
            int rowOnes = 0, colOnes = 0;
            for (int j = 0; j < 3; j++) {
                if (approxReal(getEntry(rep->images[g], i, j), 1.0, 1e-12)) rowOnes++;
                if (approxReal(getEntry(rep->images[g], j, i), 1.0, 1e-12)) colOnes++;
            }
            if (rowOnes != 1 || colOnes != 1) permOk = false;
        }
    }
    CHECK(permOk, "each regular image is a permutation matrix");

    freeRepresentation(rep);
    freeGroup(Z3);
}

